const crypto = require('crypto');

const appSecret = $env.WHATSAPP_APP_SECRET;
const signature = $json.headers['x-hub-signature-256'];

let binaryDataBuffer;
try {
  binaryDataBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
} catch (e) {
  throw new Error('Failed to read raw body from binary data: ' + e.message);
}

const body = binaryDataBuffer.toString('utf8');

if (!signature) {
  throw new Error('Missing X-Hub-Signature-256 header');
}

const expectedSignature = 'sha256=' + crypto
  .createHmac('sha256', appSecret)
  .update(body)
  .digest('hex');

if (signature !== expectedSignature) {
  throw new Error('Invalid webhook signature — request rejected');
}

return [{ json: $json }];

