const text = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text || '';
let parsed = { name: null, company: null, email: null, ride: null };
try {
  const jsonStr = text.replace(/```json/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(jsonStr);
} catch (e) {}

if (parsed.ride) {
  const v = String(parsed.ride).toLowerCase().trim();
  if (v === '1' || v.includes('helicopter')) parsed.ride = 'Helicopter';
  else if (v === '2' || v.includes('yacht')) parsed.ride = 'Yacht';
  else if (v === '3' || v.includes('jet') || v.includes('private')) parsed.ride = 'Private';
  else if (v === '4' || v.includes('car') || v.includes('luxury')) parsed.ride = 'Cab';
  else if (v === '5' || v.includes('other')) parsed.ride = 'Incoming';
}

const isValidEmail = parsed.email && parsed.email.includes('@') && parsed.email.includes('.');
const allFieldsPresent = parsed.name && parsed.company && parsed.email && parsed.ride && isValidEmail;

return [{
  json: {
    all_fields_present: !!allFieldsPresent,
    name: parsed.name,
    company: parsed.company,
    email: parsed.email,
    ride: parsed.ride
  }
}];
